import { expectStatus, test } from "../../fixtures";

test("Audit trails from another tenant are invisible", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor that belongs to the Globex Procurement tenant
  const member = await apiAs("member");
  const globexVendor = await factory.vendor({ as: "otherTenant" });

  // Act: the Northwind member requests that vendor's audit trail
  const response = await member.get(`/api/vendors/${globexVendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
